package com.kisanmitra.offer;
import com.kisanmitra.listing.*; import com.kisanmitra.user.User; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/offers") @RequiredArgsConstructor public class OfferController { private final OfferRepository offers; private final ListingRepository listings;
 @PostMapping public ResponseEntity<?> create(@RequestBody Map<String,Object> b,Authentication a){ User u=user(a); Listing l=listings.findById(UUID.fromString((String)b.get("listing"))).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND)); Offer o=new Offer(); o.setListing(l);o.setBuyer(u);o.setSeller(l.getSeller());o.setPrice(((Number)b.getOrDefault("price",0)).doubleValue());o.setQuantity(((Number)b.getOrDefault("quantity",0)).doubleValue());o.setUnit((String)b.getOrDefault("unit",l.getUnit()));o.setMessage((String)b.getOrDefault("message","")); return ResponseEntity.status(201).body(Map.of("success",true,"data",offers.save(o))); }
 @GetMapping("/me") public Map<String,Object> mine(Authentication a){return Map.of("success",true,"data",offers.findByBuyerIdOrderByCreatedAtDesc(user(a).getId()));}
 @GetMapping("/listing/{id}") public Map<String,Object> listing(@PathVariable UUID id){return Map.of("success",true,"data",offers.findByListingIdOrderByCreatedAtDesc(id));}
 @PostMapping("/{id}/reject") public Map<String,Object> reject(@PathVariable UUID id,Authentication a){Offer o=offers.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND)); if(!o.getSeller().getId().equals(user(a).getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);o.setStatus("rejected");return Map.of("success",true,"data",offers.save(o));}
 @PostMapping("/{id}/accept") public Map<String,Object> accept(@PathVariable UUID id,Authentication a){Offer o=offers.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!o.getSeller().getId().equals(user(a).getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);o.setStatus("accepted");return Map.of("success",true,"data",offers.save(o));}
 private User user(Authentication a){if(a==null||!(a.getPrincipal() instanceof User u))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return u;}
}
